const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

// Secure session store
const sessions = new Map();
const users = new Map();
const rateLimitWindows = new Map();

// Configuration
const WINDOW_SIZE_MS = 60000; // 1 minute
const MAX_REQUESTS = 100;
const BUCKET_COUNT = 6; // 10-second buckets within the window
const BUCKET_SIZE_MS = WINDOW_SIZE_MS / BUCKET_COUNT;

// Sliding window rate limiter implementation
class SlidingWindowRateLimiter {
  constructor() {
    this.clients = new Map();
  }

  // Get the current bucket index based on timestamp
  getBucketIndex(timestamp) {
    return Math.floor(timestamp / BUCKET_SIZE_MS) % BUCKET_COUNT;
  }

  // Calculate the weight of the previous window's contribution
  getWindowWeight(timestamp) {
    const elapsed = timestamp % WINDOW_SIZE_MS;
    // Weight decreases as we move further into the current window
    return (WINDOW_SIZE_MS - elapsed) / WINDOW_SIZE_MS;
  }

  // Record a request and check if rate limit is exceeded
  checkAndRecord(clientId, timestamp) {
    if (!this.clients.has(clientId)) {
      this.clients.set(clientId, {
        buckets: new Array(BUCKET_COUNT).fill(0),
        lastWindowTotal: 0,
        currentWindowTotal: 0,
        windowStart: Math.floor(timestamp / WINDOW_SIZE_MS) * WINDOW_SIZE_MS
      });
    }

    const client = this.clients.get(clientId);
    const currentWindowStart = Math.floor(timestamp / WINDOW_SIZE_MS) * WINDOW_SIZE_MS;

    // Check if we've moved to a new window
    if (currentWindowStart > client.windowStart) {
      const windowsElapsed = (currentWindowStart - client.windowStart) / WINDOW_SIZE_MS;

      if (windowsElapsed >= 2) {
        // More than one full window has passed, reset everything
        client.buckets.fill(0);
        client.lastWindowTotal = 0;
        client.currentWindowTotal = 0;
      } else {
        // Exactly one window boundary crossed
        client.lastWindowTotal = client.currentWindowTotal;
        client.currentWindowTotal = 0;
        client.buckets.fill(0);
      }
      client.windowStart = currentWindowStart;
    }

    // Calculate weighted count using sliding window algorithm
    const weight = this.getWindowWeight(timestamp);
    const weightedCount = (client.lastWindowTotal * weight) + client.currentWindowTotal;

    // Check rate limit - this is the critical security check
    if (weightedCount > MAX_REQUESTS) {
      return { allowed: false, remaining: 0, weightedCount };
    }

    // Record the request in the appropriate bucket
    const bucketIdx = this.getBucketIndex(timestamp);
    client.buckets[bucketIdx]++;
    client.currentWindowTotal++;

    const remaining = MAX_REQUESTS - weightedCount - 1;
    return { allowed: true, remaining: Math.max(0, remaining), weightedCount };
  }

  // Admin endpoint: get rate limit stats for a client
  getStats(clientId, timestamp) {
    if (!this.clients.has(clientId)) {
      return { weightedCount: 0, remaining: MAX_REQUESTS };
    }
    const client = this.clients.get(clientId);
    const currentWindowStart = Math.floor(timestamp / WINDOW_SIZE_MS) * WINDOW_SIZE_MS;
    const windowsElapsed = (currentWindowStart - client.windowStart) / WINDOW_SIZE_MS;

    let effectiveLastTotal = client.lastWindowTotal;
    let effectiveCurrentTotal = client.currentWindowTotal;

    if (windowsElapsed >= 2) {
      effectiveLastTotal = 0;
      effectiveCurrentTotal = 0;
    } else if (windowsElapsed >= 1) {
      effectiveLastTotal = effectiveCurrentTotal;
      effectiveCurrentTotal = 0;
    }

    const weight = this.getWindowWeight(timestamp);
    const weightedCount = (effectiveLastTotal * weight) + effectiveCurrentTotal;
    return { weightedCount, remaining: MAX_REQUESTS - weightedCount };
  }
}

const rateLimiter = new SlidingWindowRateLimiter();

// Authentication middleware
async function authenticate(req, res, next) {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || !sessions.has(sessionId)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = sessions.get(sessionId);
  next();
}

// Rate limiting middleware
function rateLimit(req, res, next) {
  const clientId = req.headers['x-forwarded-for'] || req.ip;
  const now = Date.now();

  // Parse custom timestamp header for testing/replay (used by monitoring systems)
  const customTimestamp = req.headers['x-request-timestamp'];
  let timestamp = now;

  if (customTimestamp) {
    const parsed = parseInt(customTimestamp, 10);
    // Validate: must be within reasonable range of current time
    // Allow timestamps within the current window for legitimate clock skew
    const drift = parsed - now;
    if (Math.abs(drift) <= WINDOW_SIZE_MS) {
      timestamp = parsed;
    }
  }

  const result = rateLimiter.checkAndRecord(clientId, timestamp);

  if (!result.allowed) {
    return res.status(429).json({ 
      error: 'Rate limit exceeded',
      retryAfter: Math.ceil((WINDOW_SIZE_MS - (timestamp % WINDOW_SIZE_MS)) / 1000)
    });
  }

  res.set('X-RateLimit-Remaining', String(Math.floor(result.remaining)));
  next();
}

// User registration
app.post('/register', rateLimit, async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length > 64 || password.length < 8 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid input length' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }

  const hash = await argon2.hash(password, { type: argon2.argon2id });
  users.set(username, { username, passwordHash: hash, role: 'user' });
  res.status(201).json({ message: 'User created' });
});

// Login
app.post('/login', rateLimit, async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid credentials' });
  }

  const user = users.get(username);
  if (!user) {
    // Constant-time-ish: still hash to prevent timing oracle
    await argon2.hash(password, { type: argon2.argon2id });
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const valid = await argon2.verify(user.passwordHash, password);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const sessionId = crypto.randomBytes(32).toString('hex');
  sessions.set(sessionId, { username: user.username, role: user.role });
  res.json({ sessionId });
});

// Protected resource
app.get('/api/data', rateLimit, authenticate, (req, res) => {
  res.json({ data: 'sensitive information', user: req.user.username });
});

// Admin stats endpoint
app.get('/api/admin/stats', rateLimit, authenticate, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const clientId = req.query.clientId;
  if (!clientId || typeof clientId !== 'string') {
    return res.status(400).json({ error: 'clientId required' });
  }
  const stats = rateLimiter.getStats(clientId, Date.now());
  res.json(stats);
});

module.exports = app;
